'use strict';
// Estado ficticio aislado. Ninguna petición de red ni credencial de la aplicación.
const KEY='ensaya-prototipo-v1';
const app=document.querySelector('#app'),dialog=document.querySelector('#dialogo');
const e=v=>String(v??'').replace(/[&<>"']/g,c=>({'&':'&amp;','<':'&lt;','>':'&gt;','"':'&quot;',"'":'&#39;'}[c]));
const money=n=>new Intl.NumberFormat('es-PE',{style:'currency',currency:'PEN'}).format(n/100);
const dateOffset=n=>{const d=new Date();d.setDate(d.getDate()+n);return new Intl.DateTimeFormat('en-CA',{timeZone:'America/Lima',year:'numeric',month:'2-digit',day:'2-digit'}).format(d);};
const fmtDate=d=>new Intl.DateTimeFormat('es-PE',{day:'numeric',month:'long',year:'numeric',timeZone:'America/Lima'}).format(new Date(d+'T12:00:00-05:00'));
const stamp=(day,time)=>new Date(`${day}T${time}:00-05:00`).getTime();
const now=()=>Date.now();
function labelControls(root){
  root.querySelectorAll('label').forEach((label,i)=>{
    const input=label.querySelector('input,select,textarea');if(!input)return;
    const name=[...label.childNodes].filter(n=>n.nodeType===3).map(n=>n.textContent.trim()).join(' ').trim();
    if(name)input.setAttribute('aria-label',name);
    const hint=label.querySelector('small');if(hint){hint.id=`${root===dialog?'dialog':'screen'}-ayuda-${i}`;input.setAttribute('aria-describedby',hint.id);}
  });
}
function seed(){const today=dateOffset(0),tomorrow=dateOffset(1);return {role:'musico',seq:10,
  rooms:[{id:'r1',name:'Sala Wari',description:'Ideal para bandas de hasta 5 integrantes.',price:3000,stock:1,active:true},{id:'r2',name:'Sala Huamanga',description:'Más espacio para bandas de hasta 8 integrantes.',price:4500,stock:1,active:true},{id:'r3',name:'Sala Acústica',description:'Un formato íntimo para dúos y solistas.',price:2500,stock:1,active:true}],
  equipment:[{id:'e1',name:'Micrófono dinámico',description:'Voz e instrumentos · por ensayo.',price:1000,stock:3,active:true},{id:'e2',name:'Amplificador de guitarra',description:'Potencia extra · por ensayo.',price:1500,stock:2,active:true},{id:'e3',name:'Teclado',description:'61 teclas · por ensayo.',price:2000,stock:1,active:true}],
  bookings:[{id:'EN-001',owner:'musico',person:'Tu banda',room:'r1',day:tomorrow,start:'19:00',end:'20:00',extras:{e1:1},total:4000,status:'CONFIRMADA'},
    {id:'EN-002',owner:'musico',person:'Tu banda',room:'r2',day:tomorrow,start:'17:00',end:'18:00',extras:{},total:4500,status:'PENDIENTE',expires:now()+600000},
    {id:'EN-003',owner:'otro',person:'Los del Sur',room:'r1',day:tomorrow,start:'18:00',end:'19:00',extras:{e2:1},total:4500,status:'CONFIRMADA'},
    {id:'EN-004',owner:'otro',person:'Ritmo Andino',room:'r2',day:today,start:'20:00',end:'22:00',extras:{},total:9000,status:'PROCESANDO'},
    {id:'EN-005',owner:'musico',person:'Tu banda',room:'r3',day:dateOffset(-3),start:'16:00',end:'17:00',extras:{},total:2500,status:'CANCELADA',reason:'Cambio de planes'},
    {id:'EN-006',owner:'musico',person:'Tu banda',room:'r1',day:dateOffset(-7),start:'18:00',end:'19:00',extras:{e1:1},total:4000,status:'CONFIRMADA'}],
  payments:[{id:'P-001',booking:'EN-001',status:'APROBADO',amount:4000},{id:'P-004',booking:'EN-004',status:'INCIERTO',amount:9000},{id:'P-005',booking:'EN-005',status:'REEMBOLSO_PENDIENTE',amount:2500},{id:'P-006',booking:'EN-006',status:'APROBADO',amount:4000},{id:'P-007',booking:'EN-003',status:'RECHAZADO',amount:4500}],
  receipts:[{id:'C-001',booking:'EN-001',status:'ENVIADA',detail:'Entrega confirmada por el proveedor simulado.'},{id:'C-003',booking:'EN-003',status:'FALLIDA',detail:'Error de mensajería simulado. La reserva sigue confirmada.'},{id:'C-006',booking:'EN-006',status:'PENDIENTE',detail:'En cola del worker simulado.'}],
  blocks:[{id:'B-001',room:'r3',day:tomorrow,start:'10:00',end:'12:00',reason:'Mantenimiento del sistema de sonido'}],
  draft:{day:tomorrow,start:'18:00',end:'19:00',room:'r2',extras:{}},step:0,payBooking:null};}
let state;try{state=JSON.parse(sessionStorage.getItem(KEY))||seed();}catch{state=seed();}
let page='inicio',tab='',filters={},flash='',formError='',menu=false,closeReturn=null,modalSubmit=null;
function save(){try{sessionStorage.setItem(KEY,JSON.stringify(state));}catch{/* La sesión sigue utilizable en memoria. */}}
const room=id=>state.rooms.find(r=>r.id===id),equipment=id=>state.equipment.find(r=>r.id===id);
const own=()=>state.bookings.filter(b=>b.owner==='musico');
const active=b=>['CONFIRMADA','PENDIENTE','PROCESANDO'].includes(b.status);
const overlaps=(a,b)=>a.day===b.day&&a.start<b.end&&b.start<a.end;
const future=b=>stamp(b.day,b.start)>now();
const badge=s=>{const ok=['CONFIRMADA','APROBADO','ENVIADA','ACTIVO','DISPONIBLE'].includes(s),bad=['CANCELADA','RECHAZADO','FALLIDA','INACTIVO','OCUPADO'].includes(s);return `<span class="pill ${ok?'ok':bad?'bad':'warn'}">${ok?'✓':bad?'×':'◷'} ${e(s.replaceAll('_',' '))}</span>`;};
const button=(text,action,cls='',attrs='')=>`<button class="btn ${cls}" data-action="${action}" ${attrs}>${text}</button>`;
const link=(text,to,cls='btn secondary')=>`<a class="${cls}" href="#${to}" ${to==='reservar'?'data-action="new-booking"':''}>${text}</a>`;
const title=(eyebrow,heading,description,action='')=>`<div class="page-heading"><div><span class="ceja">${eyebrow}</span><h1>${heading}</h1><p>${description}</p></div>${action}</div>`;
const empty=(heading,desc,action='')=>`<div class="empty"><div class="symbol" aria-hidden="true">♫</div><h3>${heading}</h3><p>${desc}</p>${action}</div>`;
const tabs=(items,selected)=>`<div class="tabs" aria-label="Filtrar vista">${items.map(([value,label,count])=>`<button class="tab" aria-pressed="${selected===value}" data-action="tab" data-value="${value}">${label}${count===undefined?'':`<span class="count">${count}</span>`}</button>`).join('')}</div>`;
const notice=(text,cls='')=>`<div class="notice ${cls}"><span aria-hidden="true">${cls==='error'?'!':cls==='success'?'✓':'ⓘ'}</span><div>${text}</div></div>`;
const art=()=>`<div class="arte-musical" role="img" aria-label="Ilustración musical de ENSAYA reutilizada: amplificador y notas"><span class="arte-orbita"></span><div class="arte-ampli"><span class="ampli-marca">ENSAYA</span><i></i><i></i><div class="ampli-controles">● ● ● ● ●</div></div><div class="arte-nota" aria-hidden="true">♬</div><div class="arte-sello">SUBE EL<br><strong>VOLUMEN</strong></div><div class="arte-ondas">${[28,48,74,42,96,64,110,40,70].map(h=>`<i style="height:${h}px"></i>`).join('')}</div></div>`;
function expire(){let changed=false;for(const b of state.bookings)if(b.status==='PENDIENTE'&&b.expires<=now()){b.status='EXPIRADA';changed=true;}if(changed)save();return changed;}
function available(r,d,exclude){return !state.bookings.some(b=>b.id!==exclude&&active(b)&&b.room===r&&overlaps(b,d))&&!state.blocks.some(b=>b.room===r&&overlaps(b,d));}
function equipmentFree(id,d){const points=[];for(const b of state.bookings){const q=b.extras[id]||0;if(!q||!active(b)||!overlaps(b,d))continue;points.push([Math.max(stamp(d.day,d.start),stamp(b.day,b.start)),q],[Math.min(stamp(d.day,d.end),stamp(b.day,b.end)),-q]);}points.sort((a,b)=>a[0]-b[0]||a[1]-b[1]);let used=0,peak=0;for(const [,v]of points){used+=v;peak=Math.max(peak,used);}return Math.max(0,equipment(id).stock-peak);}
function total(d){const minutes=(stamp(d.day,d.end)-stamp(d.day,d.start))/60000;return Math.round((room(d.room)?.price||0)*minutes/60)+Object.entries(d.extras).reduce((s,[id,q])=>s+(equipment(id)?.price||0)*q,0);}
function dateValid(d){return !!d.day&&!!d.start&&!!d.end&&d.end>d.start&&stamp(d.day,d.start)>now();}
function canCancel(b){return active(b)&&(state.role==='admin'||future(b));}
function navItems(){return state.role==='admin'?[['inicio','Inicio','⌂'],['reservas','Reservas','▦'],['catalogo','Salas y equipos','♫'],['bloqueos','Horarios no disponibles','◷'],['pagos','Pagos','▤'],['comprobantes','Comprobantes','▧'],['ayuda','Ayuda','?']]:[['inicio','Inicio','⌂'],['reservar','Reservar sala','＋'],['reservas','Mis reservas','▦'],['ayuda','Ayuda','?']];}
function render(){expire();const admin=state.role==='admin';document.title=`ENSAYA · ${admin?'Administración':'Músico'} · Prototipo`;const items=navItems();app.innerHTML=`<div class="layout ${admin?'admin':'musico'}"><aside id="menu" class="sidebar ${menu?'open':''}"><a href="#inicio" class="marca"><span class="emblema">≋</span><span>ENSAYA<small>AYACUCHO</small></span></a><div><p class="rol-label">${admin?'ADMINISTRACIÓN DEL ESTUDIO':'ESPACIO DEL MÚSICO'}</p><nav aria-label="Navegación ${admin?'administrativa':'del músico'}">${items.map(([id,label,icon])=>`<a href="#${id}" class="navlink ${page===id||(page.startsWith('detalle')&&id==='reservas')?'activo':''}" ${page===id?'aria-current="page"':''}><span class="icon" aria-hidden="true">${icon}</span>${label}</a>`).join('')}</nav></div><div class="sidebar-bottom"><strong>Todo listo para sonar.</strong><p class="muted">Datos ficticios. Los cambios solo duran esta sesión.</p><a href="#ayuda">¿Cómo usar ENSAYA?</a>${menu?button('Cerrar menú','menu','secondary full'):''}</div></aside><div class="work"><header class="topbar">${button('☰ Menú','menu','secondary menu-btn','aria-controls="menu" aria-expanded="'+menu+'"')}<div class="breadcrumb"><small>ENSAYA / ${admin?'Administración':'Tu espacio'}</small><strong>${e(items.find(x=>x[0]===page)?.[1]||'Detalle de reserva')}</strong></div><div class="role-switch"><label for="rol">Ver prototipo como</label><select id="rol" aria-label="Ver prototipo como"><option value="musico" ${!admin?'selected':''}>Músico</option><option value="admin" ${admin?'selected':''}>Administrador</option></select><span class="avatar" aria-hidden="true">${admin?'A':'M'}</span></div></header><main id="contenido" tabindex="-1" class="content">${flash?notice(e(flash),'success'):''}${content()}<footer class="footer"><span>ENSAYA · Ayacucho</span><span>Sin cobros ni envíos reales · Prototipo independiente</span></footer></main></div>${!admin?`<nav class="mobile-nav" aria-label="Navegación móvil">${items.map(([id,label,icon])=>`<a href="#${id}" ${page===id?'aria-current="page"':''}><span aria-hidden="true">${icon}</span>${id==='reservar'?'Reservar':label}</a>`).join('')}</nav>`:''}</div>`;labelControls(app);save();}
function content(){if(page.startsWith('detalle/'))return detail(page.split('/')[1]);switch(page){case'inicio':return state.role==='admin'?adminHome():musicianHome();case'reservar':return booking();case'reservas':return reservations();case'catalogo':return catalog();case'bloqueos':return blocks();case'pagos':return payments();case'comprobantes':return receipts();case'ayuda':return help();default:return empty('Pantalla no disponible','Vuelve al inicio del prototipo.',link('Ir al inicio','inicio'));}}
function musicianHome(){const pending=own().find(b=>b.status==='PENDIENTE');const next=own().filter(b=>b.status==='CONFIRMADA'&&future(b)).sort((a,b)=>stamp(a.day,a.start)-stamp(b.day,b.start))[0];return title('TU MÚSICA, TU ESPACIO','Hola, ¿cuándo ensayamos?','Reserva tu sala y encuentra aquí todo lo que necesitas para tu próximo ensayo.')+`${pending?notice(`<div class="row"><div><strong>Tienes una reserva pendiente de pago</strong><p>${e(room(pending.room)?.name)} · ${money(pending.total)} · <span data-clock="${pending.id}">${clock(pending)}</span> para confirmar.</p></div>${button('Completar pago','resume','','data-id="'+pending.id+'"')}</div>`,'warn'):''}<div class="stack"><section class="hero card"><div><span class="ceja">QUE LO SIGUIENTE SEA UN ENSAYO</span><h2>Tu banda pone la música.<br>Nosotros, el espacio.</h2><p>Elige un horario, compara salas y añade solo los equipos que necesites.</p>${link('＋ Reservar una sala','reservar','btn')}</div>${art()}</section><div class="grid2"><section class="card"><div class="section-head"><h2>Tu próximo ensayo</h2>${badge(next?'CONFIRMADA':'PENDIENTE')}</div>${next?`<h3 class="next-title">${e(room(next.room)?.name)}</h3><div class="meta"><span>▦ ${fmtDate(next.day)}</span><span>◷ ${next.start} – ${next.end} · Lima</span></div><div class="row"><strong>${money(next.total)}</strong>${link('Ver mi reserva →','detalle/'+next.id)}</div>`:empty('Tu próximo ensayo empieza aquí','Aún no tienes ensayos confirmados.',link('Reservar sala','reservar','btn'))}</section><section class="card"><span class="ceja">ASÍ DE SENCILLO</span><h2>De la idea al ensayo</h2><div class="mini-list">${[['1','Busca tu horario','Solo verás disponibilidad para tu selección.'],['2','Personaliza tu sesión','Elige sala y equipos opcionales.'],['3','Confirma y listo','Revisa el total y completa el pago simulado.']].map(([n,t,d])=>`<div class="list-item"><span class="room-mark">${n}</span><div><strong>${t}</strong><small>${d}</small></div></div>`).join('')}</div></section></div></div>`;}
function adminHome(){const day=dateOffset(0),today=state.bookings.filter(b=>b.day===day&&active(b)),pending=state.bookings.filter(b=>b.status==='PENDIENTE'),uncertain=state.payments.filter(p=>p.status==='INCIERTO');return title('CONTROL DEL ESTUDIO','Todo a tiempo. Todo en su lugar.','Una vista práctica para organizar los ensayos y atender lo que necesita tu atención.',link('Ver agenda de hoy','reservas','btn'))+`<div class="stack"><div class="grid3">${[[today.length,'Reservas de hoy','Ensayos activos del '+fmtDate(day)],[pending.length,'Pendientes de pago','Horarios protegidos por diez minutos'],[uncertain.length,'Pagos por conciliar','Resultados inciertos del simulador']].map(([n,t,d])=>`<section class="card stat"><div><span class="ceja">${t}</span><small>${d}</small></div><strong>${n}</strong></section>`).join('')}</div>${uncertain.length?notice(`<div class="row"><div><strong>Hay ${uncertain.length} pago por revisar</strong><p>Conservamos el horario hasta resolver el resultado incierto.</p></div>${link('Revisar pagos','pagos')}</div>`,'warn'):''}<section class="card"><div class="section-head"><h2>Próximos ensayos</h2>${link('Ver todas las reservas →','reservas','btn ghost')}</div>${bookingTable(state.bookings.filter(b=>active(b)&&future(b)).sort((a,b)=>stamp(a.day,a.start)-stamp(b.day,b.start)).slice(0,5),true)}</section><div class="grid2"><section class="card"><h2>¿Una sala no estará disponible?</h2><p class="muted">Bloquea el horario por mantenimiento o cierre. Las reservas existentes se conservan.</p>${link('Gestionar horarios no disponibles','bloqueos')}</section><section class="card"><h2>Tu catálogo, al día</h2><p class="muted">Administra las salas, sus tarifas y los equipos que se pueden añadir a un ensayo.</p>${link('Administrar salas y equipos','catalogo')}</section></div><small>Indicadores calculados únicamente con los registros ficticios de esta sesión.</small></div>`;}
function bookingTable(list,admin=false){return list.length?`<div class="table-wrap booking-table"><table><thead><tr><th>${admin?'Cliente y sala':'Sala'}</th><th>Fecha y horario · Lima</th><th>Estado</th><th>Total</th><th><span class="sr">Acciones</span></th></tr></thead><tbody>${list.map(b=>`<tr><td data-label="Sala / cliente"><strong>${e(admin?b.person:room(b.room)?.name)}</strong><small>${admin?e(room(b.room)?.name):e(b.id)}</small></td><td data-label="Fecha y horario">${fmtDate(b.day)}<small>${b.start} – ${b.end}</small></td><td data-label="Estado">${badge(b.status)}</td><td data-label="Total">${money(b.total)}</td><td>${link('Ver detalle','detalle/'+b.id,'btn ghost small')}</td></tr>`).join('')}</tbody></table></div>`:empty('No hay reservas en esta vista','Prueba otros filtros o selecciona otra pestaña.');}
function reservations(){if(state.role==='musico'){const list=own();const groups={proximas:list.filter(b=>active(b)&&b.status!=='PENDIENTE'&&future(b)),pendientes:list.filter(b=>b.status==='PENDIENTE'),historial:list.filter(b=>!active(b)||!future(b))};const t=tab||'proximas';return title('TUS ENSAYOS','Mis reservas','Consulta tus horarios, completa un pago pendiente o revisa tus ensayos anteriores.',link('＋ Reservar sala','reservar','btn'))+`<section class="card">${tabs([['proximas','Próximas',groups.proximas.length],['pendientes','Pendientes de pago',groups.pendientes.length],['historial','Historial',groups.historial.length]],t)}${bookingTable(groups[t]||[])}</section>`;}
  const t=tab||'agenda';let list=state.bookings.filter(b=>(!filters.day||b.day===filters.day)&&(!filters.room||b.room===filters.room)&&(!filters.status||b.status===filters.status));const day=filters.day||dateOffset(0);return title('ORGANIZA LOS ENSAYOS','Reservas','Encuentra un ensayo por fecha, sala o estado. Todos los horarios se muestran en hora de Lima.')+`<section class="card">${tabs([['agenda','Agenda diaria'],['lista','Listado']],t)}<form id="filtros-reservas" class="filters"><label>Fecha<input type="date" name="day" value="${e(filters.day??dateOffset(0))}"></label><label>Sala<select name="room"><option value="">Todas las salas</option>${state.rooms.map(r=>`<option value="${r.id}" ${filters.room===r.id?'selected':''}>${e(r.name)}</option>`).join('')}</select></label><label>Estado<select name="status"><option value="">Todos los estados</option>${['CONFIRMADA','PENDIENTE','PROCESANDO','CANCELADA','EXPIRADA'].map(s=>`<option ${filters.status===s?'selected':''}>${s}</option>`).join('')}</select></label><button class="btn" type="submit">Aplicar filtros</button>${button('Limpiar','clear-filters','secondary','type="button"')}</form>${t==='lista'?bookingTable(list,true):`<p class="muted">${fmtDate(day)} · Vista por sala</p><div class="agenda">${state.rooms.filter(r=>!filters.room||r.id===filters.room).map(r=>{const events=list.filter(b=>b.room===r.id&&b.day===day&&active(b)).sort((a,b)=>a.start.localeCompare(b.start));const bs=state.blocks.filter(b=>b.room===r.id&&b.day===day&&!filters.status);return `<section class="agenda-col"><h3>${e(r.name)}</h3>${events.map(b=>`<button class="agenda-event" data-action="detail" data-id="${b.id}"><strong>${b.start} – ${b.end}</strong><small>${e(b.person)}</small>${badge(b.status)}</button>`).join('')}${bs.map(b=>`<div class="agenda-event block"><strong>${b.start} – ${b.end}</strong><small>Horario no disponible · ${e(b.reason)}</small></div>`).join('')}${!events.length&&!bs.length?'<p class="muted">Sin ensayos ni bloqueos para estos filtros.</p>':''}</section>`;}).join('')}</div>`}</section>`;}
function summary(d,b){return `<details class="summary card" ${matchMedia('(min-width:901px)').matches?'open':''}><summary>Tu ensayo · ${money(b?.total??total(d))}</summary><div class="summary-content"><div class="row"><span class="muted">Sala</span><strong>${e(room(d.room)?.name||'Por elegir')}</strong></div><p><small>${fmtDate(d.day)}<br>${d.start} – ${d.end} · Lima</small></p><div class="row"><span class="muted">Sala por duración</span><strong>${money(Math.round((room(d.room)?.price||0)*(stamp(d.day,d.end)-stamp(d.day,d.start))/3600000))}</strong></div>${Object.entries(d.extras).filter(([,q])=>q>0).map(([id,q])=>`<div class="row"><span>${q} × ${e(equipment(id)?.name)}</span><strong>${money(q*(equipment(id)?.price||0))}</strong></div>`).join('')}<div class="total row"><span>Total ${b?'confirmado':'estimado'}</span><strong>${money(b?.total??total(d))}</strong></div><small>Las salas se cobran por duración. Los equipos, por ensayo. Todo es ficticio en este prototipo.</small></div></details>`;}
function booking(){const d=state.draft,step=state.step,b=state.bookings.find(x=>x.id===state.payBooking);const steps=['Fecha y horario','Sala','Equipos opcionales','Revisar','Pago de demostración'];return title('UNA RESERVA, PASO A PASO','Prepara tu próximo ensayo','Elige lo que necesitas. Puedes volver atrás sin perder tu selección.')+`<ol class="steps" aria-label="Progreso de reserva">${steps.map((s,i)=>`<li ${i===step?'aria-current="step"':''} class="${i<step?'done':''}"><b>${i<step?'✓':i+1}</b>${s}</li>`).join('')}</ol><div class="booking-layout"><section class="card"><span class="ceja">PASO ${step+1} DE 5</span><h2 class="step-title">${['¿Cuándo quiere ensayar tu banda?','Elige el espacio para tu sonido','¿Necesitas algún equipo extra?','Revisa antes de reservar','Confirma tu ensayo'][step]}</h2>${formError?notice(e(formError),'error'):''}${bookingStep(step,d,b)}</section>${summary(d,b)}</div>`;}
function bookingStep(step,d,b){if(step===0)return `<p class="muted">Horarios en Lima. El importe de la sala depende de la duración que elijas.</p><form id="horario"><label>Fecha del ensayo<input type="date" name="day" required min="${dateOffset(0)}" value="${d.day}"></label><div class="grid2"><label>Hora de inicio<input type="time" name="start" required value="${d.start}" step="1800"></label><label>Hora de fin<input type="time" name="end" required value="${d.end}" step="1800"><small>Debe ser posterior al inicio, dentro del mismo día.</small></label></div>${notice('Ejemplo disponible mañana: Sala Huamanga de 18:00 a 19:00. Sala Wari está ocupada en ese horario.')}<div class="step-actions"><span class="muted">1. Define tu horario</span><button class="btn" type="submit">Ver salas disponibles →</button></div></form>`;
if(step===1)return `<p class="muted">${fmtDate(d.day)} · ${d.start} – ${d.end}. Compara el precio por hora y selecciona una sala.</p>${state.rooms.filter(r=>r.active).map(r=>{const free=available(r.id,d);return `<button class="option ${d.room===r.id&&free?'chosen':''}" data-action="choose-room" data-id="${r.id}" aria-pressed="${d.room===r.id&&free}" ${!free?'disabled':''}><span class="room-mark" aria-hidden="true">♫</span><div><h3>${e(r.name)}</h3><small>${e(r.description)}</small>${badge(free?'DISPONIBLE':'OCUPADO')}${!free?'<small>Prueba otro horario para esta sala.</small>':''}</div><strong>${money(r.price)}<small>por hora</small></strong></button>`;}).join('')}${stepActions('Elegir equipos →',!available(d.room,d))}`;
if(step===2)return `<p class="muted">Este paso es opcional. El precio de cada equipo se cobra una vez por ensayo.</p>${state.equipment.filter(x=>x.active).map(x=>{const free=equipmentFree(x.id,d),q=d.extras[x.id]||0;return `<div class="option equipment"><div><h3>${e(x.name)}</h3><small>${money(x.price)} por ensayo · ${free} disponibles</small></div><div class="quantity">${button('−','quantity','','data-id="'+x.id+'" data-delta="-1" aria-label="Quitar '+e(x.name)+'" '+(!q?'disabled':''))}<output aria-label="Cantidad de ${e(x.name)}">${q}</output>${button('+','quantity','','data-id="'+x.id+'" data-delta="1" aria-label="Añadir '+e(x.name)+'" '+(q>=free?'disabled':''))}</div></div>`;}).join('')}<div class="step-actions">${button('← Anterior','previous','secondary')}${button('Omitir equipos','skip','secondary')}${button('Revisar reserva →','next')}</div>`;
if(step===3)return `<p class="muted">Comprueba el horario y el importe. Todavía puedes cambiar tu selección.</p><div class="review-block"><h3>${e(room(d.room)?.name)}</h3><p>${fmtDate(d.day)} · ${d.start} – ${d.end} · Lima</p>${button('Cambiar horario o sala','edit-booking','ghost small')}</div><div class="review-block"><h3>Equipos</h3>${Object.entries(d.extras).filter(([,q])=>q>0).map(([id,q])=>`<p>${q} × ${e(equipment(id)?.name)}</p>`).join('')||'<p class="muted">Sin equipos adicionales.</p>'}</div><div class="review-block row"><strong>Total estimado</strong><strong>${money(total(d))}</strong></div>${notice('Al reservar, protegemos sala y equipos durante <strong>10 minutos</strong>. Completa el pago de demostración antes de que venza el tiempo.','warn')}<small>Podrás cancelar antes del inicio. Los reembolsos se registran como pendientes; no hay transferencias reales.</small><div class="step-actions">${button('← Anterior','previous','secondary')}${button('Reservar y continuar al pago →','create-booking')}</div>`;
if(!b)return empty('No hay reserva pendiente','Comienza una nueva reserva.',button('Elegir horario','new-booking'));
if(b.status==='EXPIRADA')return notice('El tiempo de pago terminó y liberamos el horario. Puedes volver a consultar disponibilidad.','warn')+button('Buscar otro horario','new-booking');
if(b.status==='CONFIRMADA')return notice('Tu ensayo está confirmado. El comprobante de demostración quedó en cola.','success')+link('Ver mi reserva','detalle/'+b.id,'btn');
if(b.status==='PROCESANDO')return notice('El pago quedó con resultado incierto. Conservamos tu horario mientras el administrador concilia el resultado.','warn')+link('Ver estado de mi reserva','detalle/'+b.id,'btn');
return notice('Pago de demostración: no se solicitan tarjetas ni se realiza ningún cobro.')+`<div class="card"><small>Tiempo para completar el pago</small><div class="clock" data-clock="${b.id}">${clock(b)}</div><strong>${money(b.total)}</strong></div><form id="pagar"><label>Resultado del simulador<select name="scenario"><option value="approved">Aprobar pago</option><option value="rejected">Rechazar pago</option><option value="uncertain">Resultado incierto</option></select><small>Control de demostración para revisar los distintos mensajes de la interfaz.</small></label><div class="actions"><button class="btn" type="submit">Confirmar pago de demostración</button>${button('Simular vencimiento','expire','secondary','type="button" data-id="'+b.id+'"')}</div></form>`;}
function stepActions(text,disabled=false){return `<div class="step-actions">${button('← Anterior','previous','secondary')}${button(text,'next','',''+(disabled?'disabled':''))}</div>`;}
function clock(b){const s=Math.max(0,Math.ceil((b.expires-now())/1000));return `${Math.floor(s/60).toString().padStart(2,'0')}:${(s%60).toString().padStart(2,'0')}`;}
function detail(id){const b=state.bookings.find(b=>b.id===id&&(state.role==='admin'||b.owner==='musico'));if(!b)return empty('No se encontró la reserva','Elige una reserva de tu listado.',link('Ver reservas','reservas'));return title('DETALLE DE RESERVA',e(room(b.room)?.name),`${b.id} · ${state.role==='admin'?e(b.person):'Tu ensayo'}`,link('← Volver a reservas','reservas'))+`<div class="grid2"><section class="card"><div class="section-head"><h2>Tu sesión, al detalle</h2>${badge(b.status)}</div><div class="review-block"><h3>${fmtDate(b.day)}</h3><p>${b.start} – ${b.end} · Hora de Lima</p></div><div class="review-block"><h3>Equipos del ensayo</h3>${Object.entries(b.extras).filter(([,q])=>q>0).map(([id,q])=>`<div class="row"><span>${q} × ${e(equipment(id)?.name)}</span><strong>${money((equipment(id)?.price||0)*q)}</strong></div>`).join('')||'<p class="muted">Sin equipos adicionales.</p>'}</div><div class="row total"><strong>Total de la reserva</strong><strong>${money(b.total)}</strong></div>${b.reason?`<p class="muted">Motivo de cancelación: ${e(b.reason)}</p>`:''}</section><section class="card"><h2>¿Qué sigue?</h2>${b.status==='PENDIENTE'?notice(`Completa el pago antes de <span data-clock="${b.id}">${clock(b)}</span> para conservar tu horario.`,'warn'):b.status==='CONFIRMADA'?notice('Reserva confirmada. El estado del comprobante se consulta por separado.','success'):b.status==='PROCESANDO'?notice('Pago incierto. Tu horario se conserva hasta que el administrador resuelva el resultado.','warn'):notice('Este horario ya fue liberado. Puedes crear una nueva reserva.')}<div class="stack">${b.status==='PENDIENTE'&&state.role==='musico'?button('Continuar pago de demostración','resume','','data-id="'+b.id+'"'):''}${canCancel(b)?button('Cancelar reserva','cancel','danger','data-id="'+b.id+'"'):''}${state.role==='admin'&&b.status==='PROCESANDO'?link('Revisar pago incierto','pagos'):''}${link('Entender estados y cancelaciones','ayuda','btn ghost')}</div><p class="muted"><small>La cancelación libera los recursos. Si hubo un pago aprobado, el reembolso queda pendiente de gestión manual.</small></p></section></div>`;}
function catalog(){const t=tab||'salas',data=t==='salas'?state.rooms:state.equipment;const list=data.filter(x=>!filters.search||x.name.toLowerCase().includes(filters.search.toLowerCase()));return title('RECURSOS DEL ESTUDIO','Salas y equipos','Mantén nombres, tarifas y disponibilidad del catálogo al día.',button('＋ Crear '+(t==='salas'?'sala':'equipo'),'resource-new','','data-type="'+t+'"'))+`<section class="card">${tabs([['salas','Salas',state.rooms.length],['equipos','Equipos',state.equipment.length]],t)}<form id="buscar" class="filters"><label>Buscar por nombre<input name="search" type="search" value="${e(filters.search||'')}" placeholder="Ej. ${t==='salas'?'Sala Wari':'Micrófono'}"></label><button class="btn secondary" type="submit">Buscar</button>${button('Limpiar','clear-filters','ghost','type="button"')}</form>${list.length?`<div class="table-wrap"><table><thead><tr><th>Recurso</th><th>Tarifa</th><th>Stock</th><th>Estado</th><th>Acciones</th></tr></thead><tbody>${list.map(r=>`<tr><td><strong>${e(r.name)}</strong><small>${e(r.description)}</small></td><td>${money(r.price)}<small>${t==='salas'?'por hora':'por ensayo'}</small></td><td>${r.stock}</td><td>${badge(r.active?'ACTIVO':'INACTIVO')}</td><td><div class="actions">${button('Editar','resource-edit','ghost small','data-id="'+r.id+'" data-type="'+t+'"')}${r.active?button('Desactivar','resource-disable','danger small','data-id="'+r.id+'" data-type="'+t+'"'):button('Activar','resource-enable','secondary small','data-id="'+r.id+'" data-type="'+t+'"')}</div></td></tr>`).join('')}</tbody></table></div>`:empty('No encontramos recursos','Prueba otro nombre o crea un recurso nuevo.')}</section>`;}
function blocks(){return title('MANTENIMIENTO Y CIERRES','Horarios no disponibles','Impide nuevas reservas en una sala durante un horario concreto. No cancela ensayos existentes.')+`<div class="grid2"><section class="card"><h2>Bloquear un horario</h2>${formError?notice(e(formError),'error'):''}<form id="bloquear"><label>Sala<select name="room" required><option value="">Elige una sala</option>${state.rooms.filter(r=>r.active).map(r=>`<option value="${r.id}">${e(r.name)}</option>`).join('')}</select></label><label>Fecha<input name="day" type="date" required min="${dateOffset(0)}" value="${dateOffset(1)}"></label><div class="grid2"><label>Desde<input name="start" type="time" required value="10:00"></label><label>Hasta<input name="end" type="time" required value="12:00"></label></div><label>Motivo<textarea name="reason" required minlength="3" maxlength="300" placeholder="Ej. mantenimiento del equipo de sonido"></textarea><small>Explica el motivo para que otros administradores lo entiendan.</small></label><button class="btn" type="submit">Bloquear horario</button></form></section><section class="card"><h2>Horarios bloqueados <span class="count">${state.blocks.length}</span></h2><div class="mini-list">${state.blocks.length?state.blocks.map(b=>`<article class="list-item"><div><h3>${e(room(b.room)?.name)}</h3><small>${fmtDate(b.day)} · ${b.start} – ${b.end}</small><p class="muted">${e(b.reason)}</p>${button('Desbloquear horario','unblock','secondary small','data-id="'+b.id+'"')}</div></article>`).join(''):empty('Todas las salas están habilitadas','No existen bloqueos manuales en esta demostración.')}</div></section></div>`;}
function payments(){const t=tab||'INCIERTO',list=state.payments.filter(p=>p.status===t);return title('CONTROL DE OPERACIONES','Pagos de demostración','Revisa resultados y concilia los inciertos. No existen cobros ni reembolsos bancarios reales.')+`<section class="card">${tabs([['INCIERTO','Por conciliar'],['APROBADO','Aprobados'],['RECHAZADO','Rechazados'],['REEMBOLSO_PENDIENTE','Reembolsos pendientes']].map(([id,label])=>[id,label,state.payments.filter(p=>p.status===id).length]),t)}${t==='INCIERTO'?notice('No liberes el horario sin resolver el pago. La conciliación siguiente solo modifica datos de demostración.','warn'):''}${list.length?`<div class="table-wrap"><table><thead><tr><th>Operación</th><th>Reserva</th><th>Importe</th><th>Resultado</th><th>Acción</th></tr></thead><tbody>${list.map(p=>`<tr><td>${p.id}</td><td>${p.booking}</td><td>${money(p.amount)}</td><td>${badge(p.status)}</td><td>${button(t==='INCIERTO'?'Conciliar simulación':'Ver detalle','payment-detail',t==='INCIERTO'?'secondary small':'ghost small','data-id="'+p.id+'"')}</td></tr>`).join('')}</tbody></table></div>`:empty('No hay operaciones en este estado','Selecciona otra pestaña para consultar el resto de pagos.')}</section>`;}
function receipts(){const t=tab||'PENDIENTE',list=state.receipts.filter(p=>p.status===t);return title('ENVÍOS ASÍNCRONOS','Comprobantes','El envío se procesa después del pago. Un fallo de mensajería conserva la reserva confirmada.')+`<section class="card">${tabs(['PENDIENTE','ENVIADA','FALLIDA'].map(s=>[s,({PENDIENTE:'Pendientes',ENVIADA:'Enviados',FALLIDA:'Fallidos'})[s],state.receipts.filter(x=>x.status===s).length]),t)}${list.length?`<div class="table-wrap"><table><thead><tr><th>Comprobante</th><th>Reserva</th><th>Estado de envío</th><th>Acción</th></tr></thead><tbody>${list.map(p=>`<tr><td>${p.id}</td><td>${p.booking}</td><td>${badge(p.status)}</td><td>${button('Ver comprobante','receipt-detail','ghost small','data-id="'+p.id+'"')}</td></tr>`).join('')}</tbody></table></div>`:empty('No hay comprobantes en este estado','Los comprobantes nuevos aparecerán al confirmar un pago de demostración.')}</section>`;}
function help(){const admin=state.role==='admin';const questions=admin?[
['¿Por dónde empiezo cada día?','Abre Inicio para ver los ensayos del día y los pagos por conciliar. Usa Reservas → Agenda diaria para revisar horarios por sala.'],['¿Qué diferencia hay entre agenda y listado?','La agenda muestra los ensayos activos y bloqueos de una fecha por sala. El listado incluye también cancelados y expirados, con filtros de fecha, sala y estado.'],['¿Cómo cierro una sala por mantenimiento?','En Horarios no disponibles elige sala, fecha, inicio, fin y motivo. Un horario con una reserva activa no se puede bloquear. Desbloquear vuelve a habilitar el intervalo.'],['¿Qué hago con un pago incierto?','Revisa Pagos → Por conciliar. En el prototipo puedes simular aprobación o rechazo. El horario se conserva mientras el pago siga sin resolución.'],['¿Cuándo debo cancelar una reserva?','Usa el detalle de reserva y registra el motivo de fuerza mayor. Si existe pago aprobado, queda un reembolso pendiente: no se transfiere dinero automáticamente.'],['¿Un comprobante fallido cancela el ensayo?','No. El resultado del envío es independiente de la reserva confirmada. Aquí puedes revisar el motivo de fallo y simular el procesamiento de uno pendiente.'],['¿Puedo desactivar un recurso reservado?','El prototipo impide desactivar salas o equipos asociados a reservas futuras activas. Primero deben resolverse esas reservas.']]:[
['¿Cómo reservo una sala?','Pulsa Reservar sala. Elige fecha y horario, selecciona una sala disponible, añade equipos si los necesitas y revisa el total antes de confirmar.'],['¿Qué incluye el precio?','La tarifa de la sala se multiplica por la duración real. Cada equipo adicional se cobra por unidad y por ensayo. El resumen muestra ambos conceptos por separado.'],['¿Por qué tengo diez minutos para pagar?','Durante ese tiempo protegemos la sala y los equipos elegidos. Si vence, se liberan y debes volver a consultar disponibilidad. El botón Simular vencimiento permite probarlo sin esperar.'],['¿Puedo cambiar la selección antes de pagar?','Puedes volver a los pasos anteriores antes de crear la reserva. Una vez protegida, cancela la reserva si necesitas otro horario y crea una nueva.'],['¿Cómo cancelo un ensayo?','En Mis reservas abre Ver detalle y selecciona Cancelar reserva antes del inicio. Si hubo un pago aprobado, queda un reembolso pendiente de gestión manual.'],['¿Qué significa pago de demostración?','No se pide tarjeta ni se cobra dinero. Puedes elegir aprobación, rechazo o resultado incierto para revisar los mensajes. Un pago incierto conserva el horario mientras lo revisa el administrador.'],['¿Se guardan mis cambios?','Solo en esta pestaña del navegador mediante almacenamiento de sesión. Restablecer demostración recupera los ejemplos iniciales. No se modifica la aplicación real.']];return title('UN POCO DE AYUDA','ENSAYA, paso a paso',admin?'Guía rápida para organizar el estudio y resolver situaciones frecuentes.':'Respuestas sencillas para reservar con confianza.')+`<section class="card help">${questions.map(([q,a],i)=>`<details ${i===0?'open':''}><summary>${q}</summary><p>${a}</p></details>`).join('')}</section><section class="card" style="margin-top:20px"><h2>Cómo leer los estados</h2><div class="mini-list">${[['CONFIRMADA','Ensayo confirmado mediante el simulador.'],['PENDIENTE','Horario protegido durante diez minutos para pagar.'],['PROCESANDO','Pago en curso o incierto; los recursos se conservan.'],['CANCELADA','Horario liberado por cancelación o rechazo resuelto.'],['EXPIRADA','Se agotó el plazo de pago; el horario fue liberado.']].map(([s,t])=>`<div class="list-item">${badge(s)}<small>${t}</small></div>`).join('')}</div></section>`;}
function go(to){if(location.hash==='#'+to){page=to;tab='';filters={};formError='';render();focusHeading();}else location.hash=to;}
function focusHeading(){document.querySelector('main')?.focus({preventScroll:true});window.scrollTo(0,0);}
function showDialog(heading,body,submit){closeReturn=document.activeElement;modalSubmit=submit;dialog.innerHTML=`<button class="close" data-action="close" aria-label="Cerrar diálogo">×</button><h2 id="dialogo-titulo">${heading}</h2>${body}<p class="dialog-error" role="alert" id="dialog-error"></p>`;labelControls(dialog);dialog.showModal();}
dialog.addEventListener('close',()=>{if(closeReturn?.isConnected)closeReturn.focus();else document.querySelector('main')?.focus({preventScroll:true});});
dialog.addEventListener('keydown',ev=>{
  if(ev.key!=='Tab')return;
  const controls=[...dialog.querySelectorAll('button,input,select,textarea,a[href]')].filter(el=>!el.disabled&&el.checkVisibility());
  const first=controls[0],last=controls.at(-1);
  if(ev.shiftKey&&(document.activeElement===first||document.activeElement===dialog)){ev.preventDefault();last?.focus();}
  else if(!ev.shiftKey&&document.activeElement===last){ev.preventDefault();first?.focus();}
});
function dialogError(message){document.querySelector('#dialog-error').textContent=message;}
function alertMessage(message){document.querySelector('#anuncios').textContent=message;}
function announceAndRender(message){flash=message;render();alertMessage(message);}
function confirmCancel(id){const b=state.bookings.find(x=>x.id===id);if(!b||!canCancel(b))return;showDialog('¿Cancelar esta reserva?',`<p>${e(room(b.room)?.name)} · ${fmtDate(b.day)} · ${b.start} – ${b.end}</p>${notice('Se liberarán la sala y los equipos. Si hubo un pago aprobado, quedará un reembolso pendiente de gestión manual.','warn')}<form id="cancelar"><label>Motivo de cancelación<textarea name="reason" required minlength="3" maxlength="300" placeholder="${state.role==='admin'?'Indica el motivo de fuerza mayor':'Ej. cambio de planes de la banda'}"></textarea></label><div class="dialog-actions">${button('Conservar reserva','close','secondary','type="button"')}<button class="btn danger" type="submit">Confirmar cancelación</button></div></form>`,fd=>{if(!canCancel(b))return dialogError('La reserva ya no puede cancelarse.');const reason=fd.get('reason').trim();if(reason.length<3)return dialogError('Escribe un motivo de al menos 3 caracteres.');b.status='CANCELADA';b.reason=reason;for(const p of state.payments)if(p.booking===id&&p.status==='APROBADO')p.status='REEMBOLSO_PENDIENTE';dialog.close();announceAndRender('Reserva cancelada. El horario y los equipos quedaron libres.');});}
function resourceDialog(type,id){const data=type==='salas'?state.rooms:state.equipment,r=data.find(x=>x.id===id);showDialog(`${r?'Editar':'Crear'} ${type==='salas'?'sala':'equipo'}`,`<p class="muted">Tarifa en soles ${type==='salas'?'por hora de uso':'por unidad y ensayo'}.</p><form id="recurso"><label>Nombre<input name="name" required minlength="3" maxlength="80" value="${e(r?.name||'')}" placeholder="${type==='salas'?'Ej. Sala Centro':'Ej. Micrófono dinámico'}"></label><label>Descripción<textarea name="description" required maxlength="300">${e(r?.description||'')}</textarea></label><div class="grid2"><label>Precio en soles<input name="price" type="number" min="0.01" max="10000" step="0.01" required value="${r?(r.price/100).toFixed(2):''}"></label>${type==='equipos'?`<label>Unidades disponibles<input name="stock" type="number" min="1" max="100" step="1" required value="${r?.stock||1}"></label>`:''}</div><div class="dialog-actions">${button('Cancelar','close','secondary','type="button"')}<button type="submit" class="btn">Guardar ${type==='salas'?'sala':'equipo'}</button></div></form>`,fd=>{const name=fd.get('name').trim(),description=fd.get('description').trim(),price=Math.round(Number(fd.get('price'))*100),stock=type==='salas'?1:Number(fd.get('stock'));if(name.length<3||!description||!Number.isFinite(price)||price<=0||!Number.isInteger(stock)||stock<1)return dialogError('Revisa el nombre, descripción, precio y unidades.');if(data.some(x=>x.id!==id&&x.name.toLowerCase()===name.toLowerCase()))return dialogError('Ya existe un recurso con ese nombre.');if(r&&stock<r.stock&&state.bookings.some(b=>active(b)&&future(b)&&b.extras[r.id]))return dialogError('No reduzcas el stock mientras existan reservas futuras del equipo.');if(r)Object.assign(r,{name,description,price,stock});else data.push({id:'demo-'+(++state.seq),name,description,price,stock,active:true});dialog.close();announceAndRender('Catálogo de demostración actualizado.');});}
function addReceipt(b){if(!state.receipts.some(x=>x.booking===b.id))state.receipts.push({id:'C-'+(++state.seq),booking:b.id,status:'PENDIENTE',detail:'Comprobante en cola del worker simulado.'});}
function paymentDialog(id){const p=state.payments.find(x=>x.id===id),b=state.bookings.find(x=>x.id===p?.booking);if(!p||!b)return;const uncertain=p.status==='INCIERTO';showDialog(uncertain?'Conciliar pago simulado':'Detalle de operación',`<p>${e(p.id)} · Reserva ${e(p.booking)}</p><div class="row"><strong>${money(p.amount)}</strong>${badge(p.status)}</div><p class="muted">${p.status==='REEMBOLSO_PENDIENTE'?'Reembolso pendiente de gestión manual. Esta pantalla no transfiere dinero.':'Esta operación no representa un cargo bancario.'}</p>${uncertain?`<form id="conciliar"><label>Resultado de conciliación<select name="result"><option value="APROBADO">Simular aprobación</option><option value="RECHAZADO">Simular rechazo</option></select></label><p class="muted">Aprobar confirma la reserva; rechazar la cancela y libera los recursos.</p><div class="dialog-actions">${button('Volver','close','secondary','type="button"')}<button type="submit" class="btn">Aplicar resultado simulado</button></div></form>`:`<div class="dialog-actions">${button('Cerrar','close','secondary')}</div>`}`,fd=>{if(p.status!=='INCIERTO')return dialogError('La operación ya fue resuelta.');p.status=fd.get('result');if(b.status==='CANCELADA'){if(p.status==='APROBADO')p.status='REEMBOLSO_PENDIENTE';}else{b.status=p.status==='APROBADO'?'CONFIRMADA':'CANCELADA';if(b.status==='CONFIRMADA')addReceipt(b);}dialog.close();announceAndRender('Conciliación simulada registrada.');});}
function receiptDialog(id){const c=state.receipts.find(x=>x.id===id),b=state.bookings.find(b=>b.id===c?.booking);if(!c||!b)return;showDialog('Comprobante de demostración',`<p>${e(c.id)} · Reserva ${e(c.booking)}</p><div class="row"><strong>${money(b.total)}</strong>${badge(c.status)}</div><p>${e(room(b.room)?.name)}<br>${fmtDate(b.day)} · ${b.start} – ${b.end}</p><p class="muted">${e(c.detail)}</p>${notice('Documento demostrativo sin validez tributaria. No se envían correos reales.')}<div class="dialog-actions">${button('Cerrar','close','secondary')}${c.status==='PENDIENTE'?button('Simular envío correcto','send-receipt','','data-id="'+id+'"'):''}</div>`);}
document.addEventListener('click',ev=>{const el=ev.target.closest('[data-action]');if(!el)return;ev.preventDefault();const a=el.dataset.action,id=el.dataset.id;const d=state.draft;flash='';switch(a){
case'menu':menu=!menu;render();if(menu)document.querySelector('.sidebar a').focus();break;
case'close':dialog.close();break;
case'reset':showDialog('¿Restablecer la demostración?',`<p>Se borrarán únicamente los cambios ficticios de esta pestaña. La aplicación real no se modifica.</p><div class="dialog-actions">${button('Conservar cambios','close','secondary')}${button('Restablecer','reset-confirm')}</div>`);break;
case'reset-confirm':state=seed();save();dialog.close();page='inicio';tab='';filters={};formError='';location.hash='inicio';announceAndRender('Demostración restablecida.');break;
case'tab':tab=el.dataset.value;formError='';render();document.querySelector(`[data-value="${tab}"]`)?.focus();break;
case'clear-filters':filters={day:page==='reservas'&&state.role==='admin'?'':undefined};render();break;
case'detail':go('detalle/'+id);break;
case'choose-room':if(available(id,d)){d.room=id;render();document.querySelector(`[data-action="choose-room"][data-id="${id}"]`)?.focus();}break;
case'quantity':{const q=Math.max(0,Math.min(equipmentFree(id,d),(d.extras[id]||0)+Number(el.dataset.delta)));d.extras[id]=q;render();document.querySelector(`[data-action="quantity"][data-id="${id}"][data-delta="${el.dataset.delta}"]:not(:disabled)`)?.focus();break;}
case'next':if(state.step===1&&!available(d.room,d)){formError='La sala ya no está disponible. Elige otra sala u otro horario.';}else{state.step=Math.min(4,state.step+1);formError='';}render();focusHeading();break;
case'previous':state.step=Math.max(0,state.step-1);formError='';render();focusHeading();break;
case'edit-booking':state.step=0;render();break;
case'skip':d.extras={};state.step=3;render();focusHeading();break;
case'create-booking':{if(!dateValid(d)||!available(d.room,d)){formError='El horario ya no está disponible. Vuelve al primer paso para elegir otro.';render();break;}if(Object.entries(d.extras).some(([id,q])=>q>equipmentFree(id,d))){formError='Un equipo ya no tiene stock suficiente. Vuelve al paso de equipos.';render();break;}const b={...d,extras:{...d.extras},id:'EN-'+(++state.seq),owner:'musico',person:'Tu banda',total:total(d),status:'PENDIENTE',expires:now()+600000};state.bookings.push(b);state.payBooking=b.id;state.step=4;formError='';render();focusHeading();break;}
case'new-booking':state.step=0;state.payBooking=null;formError='';go('reservar');break;
case'resume':{const b=state.bookings.find(x=>x.id===id&&x.owner==='musico');if(b){state.draft={day:b.day,start:b.start,end:b.end,room:b.room,extras:{...b.extras}};state.payBooking=b.id;state.step=4;go('reservar');}break;}
case'expire':{const b=state.bookings.find(x=>x.id===id);if(b?.status==='PENDIENTE'){b.expires=now()-1;expire();render();alertMessage('El plazo venció y el horario quedó libre.');}break;}
case'cancel':confirmCancel(id);break;
case'resource-new':resourceDialog(el.dataset.type);break;
case'resource-edit':resourceDialog(el.dataset.type,id);break;
case'resource-enable':{const r=[...state.rooms,...state.equipment].find(x=>x.id===id);r.active=true;announceAndRender('Recurso activado.');break;}
case'resource-disable':{const r=[...state.rooms,...state.equipment].find(x=>x.id===id);const busy=state.bookings.some(b=>active(b)&&future(b)&&(b.room===id||b.extras[id]));showDialog(busy?'Este recurso tiene reservas futuras':'¿Desactivar '+e(r.name)+'?',`<p>${busy?'Primero resuelve las reservas futuras que utilizan este recurso. No cambiaremos su disponibilidad.':'Dejará de aparecer para nuevas reservas. Puedes volver a activarlo desde el catálogo.'}</p><div class="dialog-actions">${button(busy?'Entendido':'Conservar recurso','close','secondary')}${!busy?button('Confirmar desactivación','disable-confirm','danger','data-id="'+id+'"'):''}</div>`);break;}
case'disable-confirm':[...state.rooms,...state.equipment].find(x=>x.id===id).active=false;dialog.close();announceAndRender('Recurso desactivado para nuevas reservas.');break;
case'unblock':{const b=state.blocks.find(x=>x.id===id);showDialog('¿Habilitar este horario?',`<p>${e(room(b.room)?.name)} · ${fmtDate(b.day)} · ${b.start} – ${b.end}</p><p>La sala volverá a estar disponible para nuevas reservas.</p><div class="dialog-actions">${button('Conservar bloqueo','close','secondary')}${button('Confirmar desbloqueo','unblock-confirm','','data-id="'+id+'"')}</div>`);break;}
case'unblock-confirm':state.blocks=state.blocks.filter(x=>x.id!==id);dialog.close();announceAndRender('Horario desbloqueado.');break;
case'payment-detail':paymentDialog(id);break;
case'receipt-detail':receiptDialog(id);break;
case'send-receipt':{const c=state.receipts.find(x=>x.id===id);c.status='ENVIADA';c.detail='Entrega confirmada por el proveedor simulado.';dialog.close();announceAndRender('Envío simulado completado.');break;}
}});
document.addEventListener('submit',ev=>{ev.preventDefault();const f=ev.target;if(!f.reportValidity())return;const fd=new FormData(f);if(dialog.contains(f)){modalSubmit?.(fd);save();return;}switch(f.id){
case'horario':{const d={...state.draft,day:fd.get('day'),start:fd.get('start'),end:fd.get('end')};if(!dateValid(d)){formError='Elige un horario futuro. La hora de fin debe ser posterior al inicio.';render();focusHeading();break;}if(d.day!==state.draft.day||d.start!==state.draft.start||d.end!==state.draft.end){d.extras={};}state.draft=d;const availableRooms=state.rooms.filter(r=>r.active&&available(r.id,d));if(!availableRooms.some(r=>r.id===d.room))d.room=availableRooms[0]?.id||'';state.step=1;formError='';render();focusHeading();break;}
case'pagar':{expire();const b=state.bookings.find(x=>x.id===state.payBooking);if(!b||b.status!=='PENDIENTE'){formError='La reserva ya no está pendiente. Revisa su estado.';render();break;}const scenario=fd.get('scenario'),status=scenario==='approved'?'APROBADO':scenario==='rejected'?'RECHAZADO':'INCIERTO';state.payments.push({id:'P-'+(++state.seq),booking:b.id,status,amount:b.total});if(status==='APROBADO'){b.status='CONFIRMADA';addReceipt(b);announceAndRender('¡Tu ensayo está confirmado! Puedes consultar el detalle de tu reserva.');}else if(status==='RECHAZADO'){b.status='CANCELADA';formError='El simulador rechazó el pago. No hubo cobro y liberamos el horario. Vuelve a elegir un horario para intentarlo de nuevo.';state.step=0;state.payBooking=null;render();}else{b.status='PROCESANDO';render();}focusHeading();break;}
case'filtros-reservas':filters=Object.fromEntries(fd.entries());render();break;
case'buscar':filters.search=fd.get('search');render();break;
case'bloquear':{const b=Object.fromEntries(fd.entries());if(!dateValid(b)||b.reason.trim().length<3){formError='Revisa el horario futuro y escribe un motivo de al menos 3 caracteres.';render();break;}if(!available(b.room,b)){formError='El horario se cruza con una reserva activa o un bloqueo. Elige otro horario.';render();break;}state.blocks.push({...b,reason:b.reason.trim(),id:'B-'+(++state.seq)});formError='';announceAndRender('Horario bloqueado. La sala no podrá reservarse en ese intervalo.');break;}
}});
document.addEventListener('change',ev=>{if(ev.target.id==='rol'){state.role=ev.target.value;page='inicio';tab='';filters={};flash='';formError='';menu=false;save();location.hash='inicio';render();focusHeading();}});
window.addEventListener('hashchange',()=>{const next=decodeURIComponent(location.hash.slice(1))||'inicio';const allowed=state.role==='admin'?['inicio','reservas','catalogo','bloqueos','pagos','comprobantes','ayuda']:['inicio','reservas','reservar','ayuda'];page=allowed.includes(next)||next.startsWith('detalle/')?next:'inicio';tab='';filters=page==='reservas'&&state.role==='admin'?{day:dateOffset(0)}:{};formError='';menu=false;render();focusHeading();});
document.addEventListener('keydown',ev=>{if(ev.key==='Escape'&&menu){menu=false;render();document.querySelector('.menu-btn')?.focus();}});
setInterval(()=>{if(expire()){render();alertMessage('Una reserva pendiente venció y liberó su horario.');}document.querySelectorAll('[data-clock]').forEach(el=>{const b=state.bookings.find(b=>b.id===el.dataset.clock);if(b)el.textContent=clock(b);});},1000);
page=location.hash.slice(1)||'inicio';if(!navItems().some(x=>x[0]===page)&&!page.startsWith('detalle/'))page='inicio';if(page==='reservas'&&state.role==='admin')filters.day=dateOffset(0);render();
